// CreateTable creates the Item table for the specified company (SQLite)
// The db parameter can be either *sql.DB or *sql.Tx
func (t *Item) CreateTable(db database.Executor, company string) error {
	return t.CreateTableWithDBType(db, company, database.DBTypeSQLite)
}

// CreateTableWithDBType creates the Item table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *Item) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := tables.CompanyTable(company, ItemTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetItemPostgresTableSchema()
	} else {
		schema = GetItemTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Item table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *Item) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := tables.CompanyTable(company, ItemTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (no)`,
		fmt.Sprintf("%s$Item$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (search_description)`,
		fmt.Sprintf("%s$Item$search_description", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index search_description: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (inventory_posting_group)`,
		fmt.Sprintf("%s$Item$inventory_posting_group", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index inventory_posting_group: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (shelf_bin_no)`,
		fmt.Sprintf("%s$Item$shelf_bin_no", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index shelf_bin_no: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (vendor_no)`,
		fmt.Sprintf("%s$Item$vendor_no", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index vendor_no: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (gen_prod_posting_group)`,
		fmt.Sprintf("%s$Item$gen_prod_posting_group", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index gen_prod_posting_group: %w", err)
	}
	var keys []sift.Key
	for _, spec := range itemSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, ItemTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, ItemTableName, keys)
}

// itemSIFTSpecs are the table's keys with sum_index_fields
func itemSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *Item) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := tables.CompanyTable(t.company, ItemTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range itemSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, ItemTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: ItemTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, ItemTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

// ========================================
// Record Methods
// ========================================

// InitWithDBType initializes a new Item record with database context and type.
// db can be *sql.DB or *sql.Tx. There is no Init without the type: the type decides the SQL
// placeholders, and a default (SQLite) silently broke code on PostgreSQL.
func (t *Item) InitWithDBType(db database.Executor, company string, dbType database.DBType) {
	t.db = db
	t.company = company
	t.dbType = dbType
	t.oldValues = nil // Fresh record, no old values
	t.applyDefaults()
}

// InitRecord initializes a new, not yet inserted record (OnNewRecord).
// The base implementation applies the YAML default values; wrappers can override
// it to supply further defaults (call the base implementation first).
func (t *Item) InitRecord() {
	t.applyDefaults()
}

// applyDefaults assigns the YAML default values and auto timestamps
func (t *Item) applyDefaults() {
	t.Allow_invoice_disc = true
	t.Reserve = 1
	t.Rounding_precision = types.MustDecimal("1")
}

// StoreOldValues stores current field values for change detection
// Call this after loading a record from the database
func (t *Item) StoreOldValues() {
	t.oldValues = itemFields.OldValues(t.fieldRef)
}

// OldValue returns a field's value as last read from or written to the database (
// xRec), e.g. the old key in OnRename; nil when the record was not loaded.
func (t *Item) OldValue(fieldName string) interface{} {
	return t.oldValues[fieldName]
}

// XRec returns the record as it was last read from or written to the database (classic xRec),
// in the same database and company: xRec := rec.XRec(); if rec.No != xRec.No { … }. For a new
// record (never read) it is a blank record with the definition's defaults.
func (t *Item) XRec() *Item {
	x := &Item{db: t.db, company: t.company, dbType: t.dbType, temp: t.temp}
	x.InitRecord()
	itemFields.SetOldValues(x.fieldRef, t.oldValues)
	return x
}

// NewItem returns a Item record in the database and company of another
// record (from) — a classic Record variable: glAcc := gtables.NewGLAccount(rec)
func NewItem(from tables.Source) *Item {
	rec := &Item{}
	rec.InitWithDBType(from.GetDB(), from.GetCompany(), from.GetDBType())
	return rec
}

// IsGlobal reports whether the table is global (no company prefix, e.g. User, Company)
func (t *Item) IsGlobal() bool {
	return false
}

// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *Item) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *Item) Get(primaryKey interface{}) bool {
	// A composite primary key (map[string]interface{}, values also as text)
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		key := itemFields.KeyFromMap(pkMap)
		return t.GetByPK(key[0].(types.Code))
	}
	// The primary key itself (a table with one primary key field)
	if key, ok := itemFields.KeyFromValue(primaryKey); ok {
		return t.GetByPK([]any{key}[0].(types.Code))
	}

	fmt.Printf("Error: Invalid primary key type for Item.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *Item) GetByPK(no types.Code) bool {
	// Collect arguments for query
	args := []interface{}{
		no,
	}
	return t.rec().Get(args)
}

// Insert inserts the record into the database
func (t *Item) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}

	// A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead of failing: on PostgreSQL
	// a failed INSERT would abort the transaction
	switch t.rec().Insert() {
	case tables.InsertFailed:
		return false
	case tables.KeyTaken:
		// INSERT fails in the classic way: "<Table> <key> already exists"
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(ItemTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *Item) InsertAll(records []*Item, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, itemFields.RowValues(r.fieldRef))
	}
	tableName := tables.CompanyTable(t.company, ItemTableName)
	return tables.InsertRows(t.exec(), t.dbType, tableName, itemFields.Columns(), rows)
}

// Modify updates the record in the database
func (t *Item) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := itemFields.KeyChanged(t.fieldRef, t.oldValues)
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// Renamed key fields that other tables refer to (Rename): carried over below
	type renamedKey struct {
		field    string
		old, new interface{}
	}
	var renamed []renamedKey
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			renamed = append(renamed, renamedKey{"no", t.oldValues["no"], t.No})
		}
	}

	switch t.rec().Modify(t.oldValues) {
	case tables.ModifyFailed:
		return false
	case tables.NothingToSave:
		return true
	}
	// A temporary record's rename stays in the record: other tables are not changed
	for _, r := range renamed {
		if t.temp != nil {
			break
		}
		if err := t.renameReferences(r.field, r.old, r.new); err != nil {
			fmt.Printf("Error: Failed to rename references to Item: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *Item) hasFieldChanged(fieldName string) bool {
	return itemFields.Changed(t.fieldRef, t.oldValues, fieldName)
}

// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *Item) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *Item) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"no": {{"BOM_Component", false, "parent_item_no", "", 0}, {"BOM_Component", false, "no", "type", 1}, {"BOM_Journal_Line", false, "item_no", "", 0}, {"Extended_Text_Header", false, "no", "table_name", 2}, {"Intrastat_Jnl_Line", false, "item_no", "", 0}, {"Item", false, "sales_qty_disc_code", "", 0}, {"Item", false, "alternative_item_no", "", 0}, {"Item_Application_Entry", false, "item_no", "", 0}, {"Item_Journal_Line", false, "item_no", "", 0}, {"Item_Journal_Line", false, "source_no", "source_type", 3}, {"Item_Ledger_Entry", false, "item_no", "", 0}, {"Item_Ledger_Entry", false, "source_no", "source_type", 3}, {"Item_Price", false, "item_no", "", 0}, {"Item_Price_Change", false, "item_no", "", 0}, {"Item_Purch_Qty_Disc", false, "item_no", "", 0}, {"Item_Translation", false, "item_no", "", 0}, {"Item_Unit_of_Measure", false, "item_no", "", 0}, {"Item_Variant", false, "item_no", "", 0}, {"Item_Vendor", false, "item_no", "", 0}, {"Phys_Inventory_Ledger_Entry", false, "item_no", "", 0}, {"Project_Budget_Entry", false, "no", "type", 1}, {"Project_Budget_Line", false, "no", "type", 1}, {"Project_Journal_Line", false, "no", "type", 1}, {"Project_Ledger_Entry", false, "no", "type", 1}, {"Purch_Cr_Memo_Line", false, "no", "type", 2}, {"Purch_Inv_Line", false, "no", "type", 2}, {"Purch_Rcpt_Line", false, "no", "type", 2}, {"Purchase_Line", false, "no", "type", 2}, {"Requisition_Line", false, "no", "type", 2}, {"Reservation_Entry", false, "item_no", "", 0}, {"Sales_Cr_Memo_Line", false, "no", "type", 2}, {"Sales_Invoice_Line", false, "no", "type", 2}, {"Sales_Line", false, "no", "type", 2}, {"Sales_Shipment_Line", false, "no", "type", 2}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		targets := []string{ref.table}
		if !ref.global {
			targets = targets[:0]
			for _, c := range companies {
				targets = append(targets, tables.CompanyTable(c, ref.table))
			}
		}
		for _, tbl := range targets {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

// refuseDeleteWhenUsed: a record still refers to this one
func (t *Item) refuseDeleteWhenUsed() error {
	return tables.RefuseDeleteWhenUsed(t.exec(), t.dbType, tables.DeletedRecord{
		Table: ItemTableName, Global: false, Company: t.company,
		KeyColumn: "no", Key: t.No, KeyText: fmt.Sprint(t.No),
	}, []tables.Reference{
		{Table: "BOM_Component", Column: "parent_item_no"},
		{Table: "BOM_Component", Column: "no", CondColumn: "type", CondValue: 1},
		{Table: "BOM_Journal_Line", Column: "item_no"},
		{Table: "Extended_Text_Header", Column: "no", CondColumn: "table_name", CondValue: 2},
		{Table: "Intrastat_Jnl_Line", Column: "item_no"},
		{Table: "Item", Column: "sales_qty_disc_code"},
		{Table: "Item", Column: "alternative_item_no"},
		{Table: "Item_Journal_Line", Column: "item_no"},
		{Table: "Item_Journal_Line", Column: "source_no", CondColumn: "source_type", CondValue: 3},
		{Table: "Item_Price", Column: "item_no"},
		{Table: "Item_Price_Change", Column: "item_no"},
		{Table: "Item_Purch_Qty_Disc", Column: "item_no"},
		{Table: "Item_Translation", Column: "item_no"},
		{Table: "Item_Unit_of_Measure", Column: "item_no"},
		{Table: "Item_Variant", Column: "item_no"},
		{Table: "Item_Vendor", Column: "item_no"},
		{Table: "Project_Budget_Entry", Column: "no", CondColumn: "type", CondValue: 1},
		{Table: "Project_Budget_Line", Column: "no", CondColumn: "type", CondValue: 1},
		{Table: "Project_Journal_Line", Column: "no", CondColumn: "type", CondValue: 1},
		{Table: "Purchase_Line", Column: "no", CondColumn: "type", CondValue: 2},
		{Table: "Requisition_Line", Column: "no", CondColumn: "type", CondValue: 2},
		{Table: "Sales_Line", Column: "no", CondColumn: "type", CondValue: 2},
	})
}

// Delete removes the record from the database
func (t *Item) Delete(runTrigger bool) bool {
	// OnDelete trigger of the business logic
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnDelete(); err != nil {
			fmt.Printf("Error: OnDelete trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
		// Refused while a record still refers to this one (refuse_delete_when_used)
		if t.temp == nil {
			if err := t.refuseDeleteWhenUsed(); err != nil {
				t.triggerErr = err
				return false
			}
		}
	}

	return t.rec().Delete()
}

// ========================================
// FlowField Calculations
// ========================================

// CalcFields calculates FlowField values
// Usage:
//
//	customer.CalcFields("balance", "balance_lcy") - Calculate specific fields
//	customer.CalcFields() - Calculate all FlowFields
func (t *Item) CalcFields(fieldNames ...string) {
	t.flow().CalcFields(fieldNames)
}

// CalcFieldsForRecords calculates FlowFields for many records at once (list pages):
// one grouped query per FlowField instead of one query per record. records are
// ToMap() results; each gets its FlowField values under the field name. With no
// field names, all FlowFields are calculated.
func (t *Item) CalcFieldsForRecords(records []map[string]interface{}, fieldNames ...string) {
	t.flow().CalcFieldsForRecords(records, fieldNames)
}

// flow is what the FlowField functions of foundation/tables need of the record
func (t *Item) flow() *tables.FlowRec {
	return &tables.FlowRec{
		Fields:     itemFields,
		Ref:        t.fieldRef,
		FlowFilter: t.flowFilterRef,
		DB:         t.db,
		Company:    t.company,
		Postgres:   t.dbType == database.DBTypePostgres,
		Outer:      "\"" + tables.CompanyTable(t.company, ItemTableName) + "\"",
		One:        t.flowFieldOf,
	}
}

// flowFieldOf calculates a FlowField for one record of a list (a record from the map, with
// this record's FlowFilters), in its map form
func (t *Item) flowFieldOf(rec map[string]any, flowField int) any {
	one := &Item{}
	one.InitWithDBType(t.db, t.company, t.dbType)
	for i := range itemFields.FlowFilters {
		*one.flowFilterRef(i) = *t.flowFilterRef(i)
	}
	one.FromMap(rec)
	f := one.flow()
	f.Calc(flowField)
	return f.MapValue(flowField)
}

// flowFilterRef returns a pointer to the FlowFilter field with index i in itemFields.FlowFilters
func (t *Item) flowFilterRef(i int) *string {
	switch i {
	case 0:
		return &t.Date_filter
	case 1:
		return &t.Dimension_1_filter
	case 2:
		return &t.Dimension_2_filter
	case 3:
		return &t.Location_filter
	case 4:
		return &t.Drop_shipment_filter
	case 5:
		return &t.Variant_filter
	case 6:
		return &t.Bin_filter
	}
	return nil
}

// ========================================
// Filtering and Search
// ========================================

// qt is what the record's Query needs to know of the table
func (t *Item) qt() tables.QueryTable {
	return tables.QueryTable{
		Fields:          itemFields,
		NumericDecimals: t.dbType != database.DBTypePostgres || t.temp != nil,
		FlowFieldKind:   t.FlowFieldFilterKind,
		FlowFieldExpr:   t.flowFieldExpr,
	}
}

// SetRange sets a range filter on a field
// Usage:
//
//	SetRange("No", "10000") - exact match (No = "10000")
//	SetRange("No", "10000", "20000") - range (No between "10000" and "20000")
//	SetRange("No") - removes the filter on the field
func (t *Item) SetRange(fieldName string, values ...interface{}) {
	t.q.SetRange(t.qt(), fieldName, values...)
}

// SetFilter sets a filter expression on a field
// Supports filter syntax: "100..200|500" (range OR exact value)
// Operators: .. (range), | (OR), * (wildcard), <> (not equal), < <= > >=, ” (blank)
// Example: customer.SetFilter("No", "001..003|005")
func (t *Item) SetFilter(fieldName, filterExpr string) {
	t.q.SetFilter(t.qt(), fieldName, filterExpr)
}

// FlowFieldFilterKind reports whether a list can be filtered on FlowField field (Sum and
// Count FlowFields: SETFILTER on a FlowField) and the kind of its values.
func (t *Item) FlowFieldFilterKind(field string) (flowfilter.Kind, bool) {
	return itemFields.FlowFieldFilterKind(field)
}

// flowFieldExpr is the SQL expression computing FlowField field for each row of a query
// on this table: a correlated subquery reading the source like CalcFieldsForRecords (the
// SIFT totals of a covering key, else the entries), with the FlowFilters set on t.
func (t *Item) flowFieldExpr(field string) (string, []interface{}) {
	return t.flow().Expr(field)
}

// SetCurrentKey sets the sort order for queries
// Unknown fields are ignored (the primary key order is used if none remain).
// Example: customer.SetCurrentKey("City", "Name")
func (t *Item) SetCurrentKey(fields ...string) {
	t.q.SetCurrentKey(t.qt(), fields...)
}

// SetAscending sets the sort direction of the current key (Ascending).
// The default is ascending.
func (t *Item) SetAscending(ascending bool) {
	t.q.Descending = !ascending
}

// SetSearch limits the records to those where any of the given fields contains text,
// case-insensitive (the list page search box). Unknown fields are ignored; an empty
// text clears the search.
func (t *Item) SetSearch(fields []string, text string) {
	t.q.SetSearch(t.qt(), fields, text)
}

// HasColumn reports whether fieldName (case-insensitive) is a stored column of this
// table. Only such names may be used in filters and sort keys.
func (t *Item) HasColumn(fieldName string) bool {
	_, ok := t.columnName(fieldName)
	return ok
}

// columnName maps a field name (case-insensitive) to its database column. Field names
// end up in SQL text (WHERE / ORDER BY / SET), so only names from this allowlist are used.
func (t *Item) columnName(fieldName string) (string, bool) {
	return itemFields.ColumnName(fieldName)
}

// Reset clears all filters (of all filter groups; back to group 0)
func (t *Item) Reset() {
	t.q.Reset()
	t.oldValues = nil
	t.cur.CloseRows()
}

// buildWhereClause builds WHERE clause from current filters and search
func (t *Item) buildWhereClause() (string, []interface{}) {
	return t.q.Where(t.qt())
}

// FilterGroup switches to filter group group and returns the current one; without an
// argument it only returns it (FilterGroup). Each group has its own filters — SetRange,
// SetFilter, GetFilter and CopyFilter work on the current group — and the filters of all
// groups apply together. Code sets filters the user must keep in group 2 and goes back to 0.
func (t *Item) FilterGroup(group ...int) int {
	return t.q.FilterGroup(group...)
}

// isKeyDateColumn: a Date column of the primary key (a blank date is types.BlankKeyDate)
func (t *Item) isKeyDateColumn(column string) bool {
	return itemFields.IsKeyDateColumn(column)
}

// cmpColumn is a column as filters, keys and the order compare it (a decimal on SQLite as a number)
func (t *Item) cmpColumn(column string) string {
	return t.qt().CmpColumn(column)
}

// cmpParam is the placeholder of a value compared with a column (a decimal on SQLite as a number)
func (t *Item) cmpParam(column string) string {
	return t.qt().CmpParam(column)
}

// getOrderByClause builds ORDER BY clause from current key and direction, with the
// arguments of its placeholders (they follow the WHERE arguments); the primary key columns
// always follow the current key, so paging never repeats or skips rows
func (t *Item) getOrderByClause() (string, []interface{}) {
	return t.q.OrderByClause(t.qt())
}

// SetPage sets a pagination window for FindSet/FindSetBuffered: return at most
// limit rows, skipping the first offset rows. A limit of 0 disables pagination
// (all matching rows are returned). Negative values are treated as 0.
func (t *Item) SetPage(limit, offset int) {
	t.cur.SetPage(limit, offset)
}

// rec is what the read functions of foundation/tables need of the record
func (t *Item) rec() *tables.Rec {
	_, inTx := t.db.(*sql.Tx)
	return &tables.Rec{
		Fields:    itemFields,
		Ref:       t.fieldRef,
		QT:        t.qt(),
		Q:         &t.q,
		Cur:       &t.cur,
		Exec:      t.exec(),
		Buffered:  t.temp != nil || inTx,
		Postgres:  t.dbType == database.DBTypePostgres,
		Table:     tables.CompanyTable(t.company, ItemTableName),
		ForUpdate: t.forUpdate(),
		Store:     t.StoreOldValues,
		TableID:   ItemTableID,
		Company:   t.company,
		Temporary: t.temp != nil,
	}
}

// FindFirst finds the first record matching current filters
// Returns true if found, false if not found
func (t *Item) FindFirst() bool {
	return t.rec().FindFirst()
}

// FindLast finds the last record matching current filters
// Returns true if found, false if not found
func (t *Item) FindLast() bool {
	return t.rec().FindLast()
}

// Count returns the number of records matching current filters
func (t *Item) Count() int {
	return t.rec().Count()
}

// FindSet opens a result set matching current filters
// Call Next() to iterate through the results
// Returns true if at least one record found, false otherwise. A temporary record, and a
// record in a transaction, reads all at once (FindSetBuffered).
func (t *Item) FindSet() bool {
	return t.rec().FindSet()
}

// Next advances to the next record: in the result set after FindSet() or FindSetBuffered(),
// else from the current record in the current key (after Get, Find, FindFirst, FindLast)
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (FindSetBuffered, or after Get/Find)
//   - Next(-3): Skip backward 3 records (FindSetBuffered, or after Get/Find)
//
// Returns true if a record was loaded, false if no more records or out of bounds
func (t *Item) Next(steps ...int) bool {
	return t.rec().Next(steps, t.findInKey)
}

// FindSetBuffered loads all filtered records into memory for bidirectional navigation
// Use this when you need to move backward/forward with Next(steps)
// Returns true if at least one record found, false otherwise
func (t *Item) FindSetBuffered() bool {
	return t.rec().FindSetBuffered()
}

// ========================================
// Phase 3: Advanced Methods
// ========================================

// IsEmpty returns true if no records match current filters
func (t *Item) IsEmpty() bool {
	return t.Count() == 0
}

// ModifyAll updates a field for all records matching current filters
// Returns the number of records modified
func (t *Item) ModifyAll(fieldName string, newValue interface{}) int {
	return t.rec().ModifyAll(fieldName, newValue)
}

// DeleteAll deletes all records matching current filters
// Returns the number of records deleted
func (t *Item) DeleteAll() int {
	return t.rec().DeleteAll()
}

// CopyFilters copies the filters (every filter group) and the current key of another record
func (t *Item) CopyFilters(from *Item) {
	t.q.CopyFilters(&from.q)
}

// GetFilters returns a string representation of current filters
// Useful for debugging and logging
func (t *Item) GetFilters() string {
	return t.q.GetFilters()
}

// ========================================
// Field Validation
// ========================================

// ValidateField validates a field and calls its OnValidate trigger
// This is equivalent to the VALIDATE function
// Usage: customer.ValidateField("Payment_terms_code", types.NewCode("30DAYS"))
func (t *Item) ValidateField(fieldName string, value interface{}) error {
	i, err := itemFields.ValidateSet(t.fieldRef, fieldName, value)
	if err != nil {
		return err
	}
	f := &itemFields.Fields[i]
	// TableRelation: the value must exist in the related table (before OnValidate) — a field
	// of an extension app while the app is enabled
	if f.Relation && (f.App == "" || extensions.Enabled(f.App)) {
		if err := tables.CheckRelation(t, t.db, t.company, t.dbType, f.Info.Name); err != nil {
			return err
		}
	}
	// OnValidate trigger of the business logic (OnValidate of the field)
	return tables.RunOnValidate(t.registeredLogic(), t, f.Trigger)
}

// ========================================
// Classic record functions
// ========================================

// FieldValue returns the value of a stored field by its number (FlowFields are not stored)
func (t *Item) FieldValue(no int) (any, bool) {
	return itemFields.FieldValue(t.fieldRef, no)
}

// flowFieldValue returns the value of a FlowField by its number, as CalcFields left it
func (t *Item) flowFieldValue(no int) (any, bool) {
	return itemFields.FlowFieldValue(t.fieldRef, no)
}

// SetFieldValue sets a stored field by its number when the value has the field's type
// (options: any option value or int); it reports whether the field was set
func (t *Item) SetFieldValue(no int, value any) bool {
	return itemFields.SetFieldValue(t.fieldRef, no, value)
}

// TransferFields copies the fields of another record that have the same field number and
// type (TransferFields): FlowFields are not copied, and with initPrimaryKey false the
// primary key fields keep their values (default true: they are copied too). No trigger runs.
func (t *Item) TransferFields(from tables.FieldValuer, initPrimaryKey ...bool) {
	copyKey := len(initPrimaryKey) == 0 || initPrimaryKey[0]
	for _, f := range t.GetFields() {
		if f.FlowField || f.PrimaryKey && !copyKey {
			continue
		}
		if v, ok := from.FieldValue(f.No); ok {
			t.SetFieldValue(f.No, v)
		}
	}
}

// CompanyName returns the company the record reads and writes (the session's company)
func (t *Item) CompanyName() string {
	return t.company
}

// ChangeCompany makes the record read and write another company's table (filters are kept);
// it reports false when the company does not exist.
func (t *Item) ChangeCompany(company string) bool {
	if !tables.CompanyExists(t.db, t.dbType, company) {
		return false
	}
	t.company = company
	return true
}

// TestField returns an error unless the field has a value — or, with a value, that value
// (TestField): the user's messages "X is required" / "X must be …"
func (t *Item) TestField(fieldName string, value ...any) error {
	no := t.FieldNo(fieldName)
	current, ok := t.FieldValue(no)
	if !ok {
		// a FlowField: its value as CalcFields left it (classic TESTFIELD after CALCFIELDS)
		current, ok = t.flowFieldValue(no)
	}
	if !ok {
		return fmt.Errorf("TestField: %s is not a field of Item", fieldName)
	}
	field := t.FieldName(no)
	if len(value) == 0 {
		if tables.IsEmptyValue(current) {
			return apperrors.FieldRequired(ItemTableName, field)
		}
		return nil
	}
	if !tables.SameValue(current, value[0]) {
		return apperrors.FieldMustBeValue(ItemTableName, field, value[0])
	}
	return nil
}

// FieldError returns an error about a field (FieldError): "<caption> <text>"; pass a
// translated text
func (t *Item) FieldError(fieldName string, text string) error {
	return apperrors.FieldErrorText(ItemTableName, strings.ToLower(fieldName), text)
}

// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *Item) CalcSums(fieldNames ...string) error {
	return t.rec().CalcSums(fieldNames)
}

// LockTable locks the table until the transaction ends (classic LOCKTABLE): on Postgres a
// table lock (tables.LockTable) and the following reads (Get, FindFirst, FindLast, FindSet)
// lock the rows they read (SELECT … FOR UPDATE); SQLite locks the whole database on write
// anyway. Use it inside a transaction.
func (t *Item) LockTable() {
	if !t.lockForUpdate {
		tables.LockTable(t.db, t.dbType, t.company, ItemTableName)
	}
	t.lockForUpdate = true
}

func (t *Item) forUpdate() string {
	if t.lockForUpdate && t.dbType == database.DBTypePostgres {
		return " FOR UPDATE"
	}
	return ""
}

// MaxStrLen returns the maximum length of a Code or Text field (0 for other fields)
func (t *Item) MaxStrLen(fieldName string) int {
	for _, f := range t.GetFields() {
		if strings.EqualFold(f.Name, fieldName) {
			return f.Length
		}
	}
	return 0
}

// GetFilter returns the filter on a field in the filter syntax ("" for none)
func (t *Item) GetFilter(fieldName string) string {
	return t.q.GetFilter(t.qt(), fieldName)
}

// exec is the database of the record's own table: the temporary record's in-memory
// database, else the record's database
func (t *Item) exec() database.Executor {
	if t.temp != nil {
		return t.temp.DB
	}
	return t.db
}

// InitTemporary makes the record temporary (Temporary): its table lives in a private
// in-memory database — Insert, Modify, Delete, Find, filters, keys and CalcSums work as usual
// and nothing reaches the real database. Triggers (Insert(true)) and FlowFields still use the
// real database (db) for other tables; a rename does not change other tables. The records
// are gone when the record is no longer used.
func (t *Item) InitTemporary(db database.Executor, company string, dbType database.DBType) error {
	t.InitWithDBType(db, company, dbType)
	store, err := tables.NewTemporaryStore()
	if err != nil {
		return err
	}
	if err := t.CreateTableWithDBType(store.DB, company, database.DBTypeSQLite); err != nil {
		return err
	}
	t.temp = store
	return nil
}

// IsTemporary reports whether the record is temporary (InitTemporary)
func (t *Item) IsTemporary() bool {
	return t.temp != nil
}

// Consistent marks the table consistent or inconsistent in the record's transaction
// (Consistent): tables.Commit refuses to commit while a table is inconsistent — e.g. G/L
// entries while the posting does not balance yet
func (t *Item) Consistent(ok bool) {
	tables.SetConsistent(t.db, ItemTableName, ok)
}

// FilterExpressions returns the filters of all filter groups as field and expression
func (t *Item) FilterExpressions() []tables.FieldFilter {
	return t.q.FilterExpressions()
}

// FilterExpressionsByGroup returns the filters of each filter group (as FilterExpressions,
// sorted by field) — a page opened from code shows group 0 as the user's filters and keeps the
// other groups fixed, so two filters on one field in different groups both apply
func (t *Item) FilterExpressionsByGroup() map[int][]tables.FieldFilter {
	return t.q.FilterExpressionsByGroup()
}

// KeyText returns the primary key of the current record as text, the values joined by ","
// (the record id of the API and the pages)
func (t *Item) KeyText() string {
	_, text := t.recordKey()
	return text
}

// CopyFilter copies the filter on a field to a field of another record (CopyFilter)
func (t *Item) CopyFilter(fieldName string, to tables.FilterTarget, toFieldName string) {
	t.q.CopyFilter(t.qt(), fieldName, to, toFieldName)
}

// GetRangeMin returns the lower end of the SetRange filter on a field (nil without one)
func (t *Item) GetRangeMin(fieldName string) interface{} {
	return t.q.RangeMin(t.qt(), fieldName)
}

// GetRangeMax returns the upper end of the SetRange filter on a field (nil without one)
func (t *Item) GetRangeMax(fieldName string) interface{} {
	return t.q.RangeMax(t.qt(), fieldName)
}

// SetRecFilter filters on the primary key of the current record (SetRecFilter)
func (t *Item) SetRecFilter() {
	t.SetRange("no", t.No)
}

// recordKey returns the primary key values of the current record and their text
func (t *Item) recordKey() ([]interface{}, string) {
	values := []interface{}{t.No}
	parts := make([]string, len(values))
	for i, v := range values {
		parts[i] = fmt.Sprint(v)
	}
	return values, strings.Join(parts, ",")
}

// Mark marks (or with false unmarks) the current record and reports whether it is marked;
// without an argument it only reports it (Mark)
func (t *Item) Mark(mark ...bool) bool {
	values, key := t.recordKey()
	return t.q.Mark(key, values, mark...)
}

// MarkedOnly limits the following reads to the marked records (MarkedOnly)
func (t *Item) MarkedOnly(only bool) {
	t.q.MarkedOnly(only)
}

// ClearMarks removes all marks (ClearMarks)
func (t *Item) ClearMarks() {
	t.q.ClearMarks()
}

// RecordId returns the table and the primary key of the current record: "Customer: C1"
func (t *Item) RecordId() string {
	_, key := t.recordKey()
	return ItemTableName + ": " + key
}

// CountApprox returns the number of records matching the filters (the same as Count)
func (t *Item) CountApprox() int {
	return t.Count()
}

// Rename gives the current (read) record a new primary key — the values in key order — and
// modifies it with the OnRename trigger; fields of other tables that refer to it follow
// (Rename). It reports false when a value has the wrong type or the modify fails.
func (t *Item) Rename(newKey ...interface{}) bool {
	numbers := []int{1}
	if len(newKey) != len(numbers) {
		return false
	}
	for i, no := range numbers {
		if !t.SetFieldValue(no, newKey[i]) {
			return false
		}
	}
	return t.Modify(true)
}

// Copy copies another record's values and filters (Copy)
func (t *Item) Copy(from *Item) {
	t.TransferFields(from)
	t.CopyFilters(from)
	// The copy is the record as read: its stored values (xRec, the key a Modify matches) are
	// the source's — a Modify after Copy changes the copied record, never the one read before
	if from.oldValues != nil {
		t.oldValues = make(map[string]interface{}, len(from.oldValues))
		for k, v := range from.oldValues {
			t.oldValues[k] = v
		}
	} else {
		t.oldValues = nil
	}
}

// Find finds a record (Find) within the filters, in the current key and direction
// (SetCurrentKey, SetAscending): "-" the first, "+" the last, "=" the record with the
// current primary key, ">" the next record after the current one, "<" the one before it.
// "=<>" combine, tried in that order: "=<>" the current record, else the one before it, else
// the next one.
func (t *Item) Find(which ...string) bool {
	how := "="
	if len(which) > 0 && which[0] != "" {
		how = which[0]
	}
	switch how {
	case "-":
		return t.findInKey("", false)
	case "+":
		return t.findInKey("", true)
	}
	if strings.Contains(how, "=") {
		// The record's key in a filter group of its own: the filters still apply (also those
		// on key fields)
		group := t.FilterGroup()
		t.FilterGroup(tables.FindKeyFilterGroup)
		t.q.ClearGroupFilters()
		t.SetRecFilter()
		found := t.FindFirst()
		t.q.ClearGroupFilters()
		t.FilterGroup(group)
		if found {
			return true
		}
	}
	if strings.Contains(how, "<") && t.findInKey("<", true) {
		return true
	}
	if strings.Contains(how, ">") && t.findInKey(">", false) {
		return true
	}
	return false
}

// findInKey reads the first record in the current key and direction — reversed for the
// last — and with seek ">"/"<" only after/before the current record
func (t *Item) findInKey(seek string, reverse bool) bool {
	return t.rec().FindInKey(seek, reverse)
}

// keyColumns returns the columns of the current key followed by the primary key's (the
// sort order of FindSet)
func (t *Item) keyColumns() []string {
	return t.q.KeyColumns(t.qt())
}

// columnValue returns the value of a stored field by its column, as an SQL argument
func (t *Item) columnValue(column string) (interface{}, bool) {
	return itemFields.ColumnValue(t.fieldRef, column)
}

// SetSelection keeps the records selected on the list a codeunit is run from (the API sets
// it from the list's selection; keys are field name → value); SetSelectionFilter applies it
func (t *Item) SetSelection(keys []map[string]interface{}) {
	t.selection = nil
	for _, key := range keys {
		var r Item
		r.FromMap(key)
		values, text := r.recordKey()
		if t.selection == nil {
			t.selection = map[string][]interface{}{}
		}
		t.selection[text] = values
	}
}

// SetSelectionFilter limits the record to the records selected on the list the codeunit was
// run from (SetSelectionFilter): several selected records are marked (MarkedOnly), else the
// filter is on the current record (SetRecFilter)
func (t *Item) SetSelectionFilter() {
	if len(t.selection) <= 1 {
		for _, values := range t.selection {
			var r Item
			r.setKeyValues(values)
			r.SetRecFilter()
			t.CopyFilters(&r)
			return
		}
		t.SetRecFilter()
		return
	}
	t.q.MarkOnly(t.selection)
}

// setKeyValues sets the primary key fields from their values (recordKey order)
func (t *Item) setKeyValues(values []interface{}) {
	i := 0
	if v, ok := values[i].(types.Code); ok {
		t.No = v
	}
	i++
	_ = i
}

